_id, island_id, COUNT(id) AS city_zaehler FROM de_0910_14.city GROUP BY owner_id, island_id UNION ALL SELECT owner_id, island_id, COUNT(id) AS city_zaehler FROM de_1311_14.city GROUP BY owner_id, island_id ) AS mavi_query GROUP BY owner_id, island_id ORDER BY owner_id;

# Q7_Alter_Master_AVI

ALTER TABLE master_avi ADD PRIMARY KEY (`owner_id`, `island_id`);

ALTER TABLE `master_avi` ADD COLUMN `Anzahl_Teilnahme` INT NULL DEFAULT NULL AFTER `Cities_Vorhanden`;
UPDATE master_avi mav INNER JOIN ( SELECT (`Anzahl_vorhanden`)  Anzahl_vorhanden, id t_id FROM teilnahme_av) AS tav ON tav.t_id = mav.owner_id SET mav.`Anzahl_Teilnahme` = tav.`Anzahl_vorhanden`;

