# Q14_Update_City

UPDATE city SET Holz_verbaut = (g1h + g2h + g3h + g4h + g5h + g6h + g7h + g8h + g9h + g10h + g11h + g12h + g13h + g14h + g15h + g16h + g17h);
UPDATE city SET Kristall_verbaut = (g1k + g2k + g3k + g4k + g5k + g6k + g7k + g8k + g9k + g10k + g11k + g12k + g13k + g14k + g15k + g16k + g17k);
UPDATE city SET Wein_verbaut = (g1w + g2w + g3w + g4w + g5w + g6w + g7w + g8w + g9w + g10w + g11w + g12w + g13w + g14w + g15w + g16w + g17w);
UPDATE city SET Schwefel_verbaut = (g1s + g2s + g3s + g4s + g5s + g6s + g7s + g8s + g9s + g10s + g11s + g12s + g13s + g14s + g15s + g16s + g17s);
UPDATE city SET Stein_verbaut = (g1q + g2q + g3q + g4q + g5q + g6q + g7q + g8q + g9q + g10q + g11q + g12q + g13q + g14q + g15q + g16q + g17q);
UPDATE city SET Baumeister_Highscore = (Holz_verbaut + Kristall_verbaut + Wein_verbaut + Schwefel_verbaut + Stein_verbaut);


# Q15 Update City

UPDATE city SET `Holz_verbaut` = CASE WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` < 180000 AND city.owner_id = avatar.id) > 0 THEN (g1h + g2h + g3h + g4h + g5h + g6h + g7h + g8h + g9h + g10h + g11h + g12h + g13h + g14h + g15h + g16h + g17h) WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` > 180001 AND `Spieldauer` < 1440000 AND city.owner_id = avatar.id) > 0 THEN ((g1h + g2h + g3h + g4h + g5h + g6h + g7h + g8h + g9h + g10h + g11h + g12h + g13h + g14h + g15h + g16h + g17h) * 0.98)WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` > 1440001 AND `Spieldauer` < 13149000 AND city.owner_id = avatar.id) > 0 THEN ((g1h + g2h + g3h + g4h + g5h + g6h + g7h + g8h + g9h + g10h + g11h + g12h + g13h + g14h + g15h + g16h + g17h) * 0.94)WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` > 13149001 AND city.owner_id = avatar.id) > 0 THEN ((g1h + g2h + g3h + g4h + g5h + g6h + g7h + g8h + g9h + g10h + g11h + g12h + g13h + g14h + g15h + g16h + g17h) * 0.86) ELSE `Holz_verbaut` END;
UPDATE city SET `Kristall_verbaut` = CASE WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` < 180000 AND city.owner_id = avatar.id) > 0 THEN (g1k + g2k + g3k + g4k + g5k + g6k + g7k + g8k + g9k + g10k + g11k + g12k + g13k + g14k + g15k + g16k + g17k) WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` > 180001 AND `Spieldauer` < 1440000 AND city.owner_id = avatar.id) > 0 THEN ((g1k + g2k + g3k + g4k + g5k + g6k + g7k + g8k + g9k + g10k + g11k + g12k + g13k + g14k + g15k + g16k + g17k) * 0.98)WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` > 1440001 AND `Spieldauer` < 13149000 AND city.owner_id = avatar.id) > 0 THEN ((g1k + g2k + g3k + g4k + g5k + g6k + g7k + g8k + g9k + g10k + g11k + g12k + g13k + g14k + g15k + g16k + g17k) * 0.94)WHEN (SELECT COUNT(id) FROM avatar WHERE `Spieldauer` > 13149001 AND city.owner_id = avatar.id) > 0 THEN ((g1k + g2k + g3k + g4k + g5k + g6k + g7k + g8k + g9k + g10k + g11k + g12k + g13k + g14k + g15k + g16k + g17k) * 0.86) ELSE `Kristall_verbaut` END;
