# Q16_Update_City

UPDATE city SET `Buerger_Ges` = (citizens + resource_workers + tradegood_workers + scientists + priests)  ;
UPDATE city SET `Holz_lagernd` = (`resource`)  ;
UPDATE city SET `Kristall_lagernd` = (`tradegood3`)  ;
UPDATE city SET `QKWS_lagernd` = (tradegood1 + tradegood2 + tradegood3 + tradegood4)  ;
UPDATE city SET `Rathauslev` = (`level`)  ;
UPDATE city SET `Res_Ges_lagernd` = (tradegood1 + tradegood2 + tradegood3 + tradegood4 + resource)  ;
UPDATE city SET `Resworkers_Holz_Lux` = (tradegood_workers + resource_workers)  ;
UPDATE city SET `Schwefel_lagernd` = (`tradegood4`)  ;
UPDATE city SET `Stein_lagernd` = (`tradegood2`)  ;
UPDATE city SET `Wein_lagernd` = (`tradegood1`)  ;
UPDATE city SET `Geblev` = (p1l+p2l+p3l+p4l+p5l+p6l+p7l+p8l+p9l+p10l+p11l+p12l+p13l+p14l+p15l+p16l+p17l)  ;
UPDATE city SET `Holz_Ges_verb_lag` = (Holz_verbaut + Holz_lagernd)  ;
UPDATE city SET `Kristall_Ges_verb_lag` = (Kristall_verbaut + Kristall_lagernd)  ;
UPDATE city SET `Res_Ges_verbaut` = (Holz_verbaut+Stein_verbaut+Kristall_verbaut+Wein_verbaut+Schwefel_verbaut)  ;
UPDATE city SET `Res_Ges_verb_lag` = (Res_Ges_verbaut + Res_Ges_lagernd)  ;
UPDATE city SET `Schwefel_Ges_verb_lag` = (Schwefel_verbaut + Schwefel_lagernd)  ;
UPDATE city SET `Stein_Ges_verb_lag` = (Stein_verbaut + Stein_lagernd)  ;
UPDATE city SET `Wein_Ges_verb_lag` = (Wein_verbaut + Wein_lagernd)  ;
UPDATE city SET `priests` = CASE WHEN `priests` IS NULL THEN 0 ELSE `priests` END;


