# Q19_Create_NoDons

CREATE TABLE IF NOT EXISTS `donation_nodon` AS SELECT DISTINCT owner_id, c.island_id FROM city c LEFT OUTER JOIN donation d ON d.avatar_id = c.owner_id AND d.island_id = c.island_id WHERE d.island_id IS NULL;
ALTER TABLE `donation_nodon` ADD PRIMARY KEY(`owner_id`, `island_id`);
ALTER TABLE `donation_nodon` ADD COLUMN `gold` INT default 0  AFTER `island_id`;
ALTER TABLE `donation_nodon` ADD COLUMN `type` INT default 0  AFTER `gold`;
INSERT INTO `donation` (`avatar_id`, `island_id`, `gold`, `type`)  SELECT `owner_id`, `island_id`, `gold`, `type` FROM `donation_nodon`;

# Q20_Update_Donation_Prep

UPDATE donation SET `Don_Wonder_Ges` = `gold` WHERE `type` = 1;
UPDATE donation SET `Don_Saegewerk_Ges` = `gold` WHERE `type` = 2;
UPDATE donation SET `DonH_Luxusminen_Ges` = `gold` WHERE `type` = 3;
UPDATE donation SET `Don_Ges` = `gold`;

