UPDATE donation d INNER JOIN ( SELECT SUM(`Don_Saegewerk_Ges`)  Don_Saegewerk_Ges, avatar_id d_avatar_id,  island_id d_island_id FROM donation GROUP BY avatar_id, island_id) AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`Don_Saegewerk_Ges` = don.`Don_Saegewerk_Ges`;
