UPDATE donation2 d INNER JOIN ( SELECT (DonH_Luxusminen_Ges) DonH_fuer_Kristallmine, avatar_id d_avatar_id, island_id d_island_id FROM donation2 INNER JOIN island ON island_id = id WHERE tradegood = '3') AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`DonH_fuer_Kristallmine` = don.`DonH_fuer_Kristallmine`;
UPDATE donation2 d INNER JOIN ( SELECT (DonH_Luxusminen_Ges) DonH_fuer_Schwefelgrube, avatar_id d_avatar_id, island_id d_island_id FROM donation2 INNER JOIN island ON island_id = id WHERE tradegood = '4') AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`DonH_fuer_Schwefelgrube` = don.`DonH_fuer_Schwefelgrube`;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Wonder_Ges - ((Don_Wonder_Ges / 100) * 66.6667)) Don_Wonder_Anteil_Wein, avatar_id d_avatar_id, island_id d_island_id FROM donation2 INNER JOIN island ON id = island_id WHERE tradegood != '1') AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`Don_Wonder_Anteil_Wein` = don.`Don_Wonder_Anteil_Wein`;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Wonder_Ges - ((Don_Wonder_Ges / 100) * 66.6667)) Don_Wonder_Anteil_Stein, avatar_id d_avatar_id, island_id d_island_id FROM donation2 INNER JOIN island ON id = island_id WHERE tradegood != '2') AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`Don_Wonder_Anteil_Stein` = don.`Don_Wonder_Anteil_Stein`;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Wonder_Ges - ((Don_Wonder_Ges / 100) * 66.6667)) Don_Wonder_Anteil_Kristall, avatar_id d_avatar_id, island_id d_island_id FROM donation2 INNER JOIN island ON id = island_id WHERE tradegood != '3') AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`Don_Wonder_Anteil_Kristall` = don.`Don_Wonder_Anteil_Kristall`;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Wonder_Ges - ((Don_Wonder_Ges / 100) * 66.6667)) Don_Wonder_Anteil_Schwefel, avatar_id d_avatar_id, island_id d_island_id FROM donation2 INNER JOIN island ON id = island_id WHERE tradegood != '4') AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`Don_Wonder_Anteil_Schwefel` = don.`Don_Wonder_Anteil_Schwefel`;
UPDATE donation2 d INNER JOIN ( SELECT SUM(`Kristall_Ges_verb_lag`) AS sum_k_verb_lag, Don_Wonder_Anteil_Kristall AS k_don_ant,d2.`avatar_id` AS d2_a_id, d2.`island_id` AS d2_i_id FROM donation2 d2 LEFT JOIN city2 c2 ON (d2.`island_id` = c2.`island_id`AND d2.`avatar_id`=c2.`owner_id`)  LEFT JOIN avatar a2 ON (d2.`avatar_id` = a2.`id` AND c2.`owner_id` = a2.`id`) GROUP BY d2.`avatar_id`, d2.`island_id`) AS aux ON (d.`avatar_id` = d2_a_id  AND d.`island_id`=d2_i_id) SET d.`Kristall_Ges_verb_lag_don` = aux.sum_k_verb_lag + aux.k_don_ant;
UPDATE donation2 d INNER JOIN ( SELECT SUM(`Schwefel_Ges_verb_lag`) AS sum_s_verb_lag, Don_Wonder_Anteil_Schwefel AS s_don_ant,d2.`avatar_id` AS d2_a_id, d2.`island_id` AS d2_i_id FROM donation2 d2 LEFT JOIN city2 c2 ON (d2.`island_id` = c2.`island_id`AND d2.`avatar_id`=c2.`owner_id`)  LEFT JOIN avatar a2 ON (d2.`avatar_id` = a2.`id` AND c2.`owner_id` = a2.`id`) GROUP BY d2.`avatar_id`, d2.`island_id`) AS aux ON (d.`avatar_id` = d2_a_id  AND d.`island_id`=d2_i_id) SET d.`Schwefel_Ges_verb_lag_don` = aux.sum_s_verb_lag + aux.s_don_ant;
UPDATE donation2 d INNER JOIN ( SELECT SUM(`Holz_Ges_verb_lag`) AS sum_h_verb_lag, (Don_Saegewerk_Ges + DonH_Luxusminen_Ges) AS h_don_ant,d2.`avatar_id` AS d2_a_id, d2.`island_id` AS d2_i_id FROM donation2 d2 LEFT JOIN city2 c2 ON (d2.`island_id` = c2.`island_id`AND d2.`avatar_id`=c2.`owner_id`)  LEFT JOIN avatar a2 ON (d2.`avatar_id` = a2.`id` AND c2.`owner_id` = a2.`id`) GROUP BY d2.`avatar_id`, d2.`island_id`) AS aux ON (d.`avatar_id` = d2_a_id  AND d.`island_id`=d2_i_id) SET d.`Holz_Ges_verb_lag_don` = aux.sum_h_verb_lag + aux.h_don_ant;
UPDATE donation2 d INNER JOIN ( SELECT SUM(`Wein_Ges_verb_lag`) AS sum_w_verb_lag, Don_Wonder_Anteil_Wein AS w_don_ant,d2.`avatar_id` AS d2_a_id, d2.`island_id` AS d2_i_id FROM donation2 d2 LEFT JOIN city2 c2 ON (d2.`island_id` = c2.`island_id`AND d2.`avatar_id`=c2.`owner_id`)  LEFT JOIN avatar a2 ON (d2.`avatar_id` = a2.`id` AND c2.`owner_id` = a2.`id`) GROUP BY d2.`avatar_id`, d2.`island_id`) AS aux ON (d.`avatar_id` = d2_a_id  AND d.`island_id`=d2_i_id) SET d.`Wein_Ges_verb_lag_don` = aux.sum_w_verb_lag + aux.w_don_ant;
UPDATE donation2 d INNER JOIN ( SELECT SUM(`Stein_Ges_verb_lag`) AS sum_q_verb_lag, Don_Wonder_Anteil_Stein AS q_don_ant,d2.`avatar_id` AS d2_a_id, d2.`island_id` AS d2_i_id FROM donation2 d2 LEFT JOIN city2 c2 ON (d2.`island_id` = c2.`island_id`AND d2.`avatar_id`=c2.`owner_id`)  LEFT JOIN avatar a2 ON (d2.`avatar_id` = a2.`id` AND c2.`owner_id` = a2.`id`) GROUP BY d2.`avatar_id`, d2.`island_id`) AS aux ON (d.`avatar_id` = d2_a_id  AND d.`island_id`=d2_i_id) SET d.`Stein_Ges_verb_lag_don` = aux.sum_q_verb_lag + aux.q_don_ant;
UPDATE donation2 d INNER JOIN ( SELECT SUM(`Res_Ges_verb_lag`) AS sum_rg_verb_lag, Don_Ges AS res_ges_don_ant,d2.`avatar_id` AS d2_a_id, d2.`island_id` AS d2_i_id FROM donation2 d2 LEFT JOIN city2 c2 ON (d2.`island_id` = c2.`island_id`AND d2.`avatar_id`=c2.`owner_id`)  LEFT JOIN avatar a2 ON (d2.`avatar_id` = a2.`id` AND c2.`owner_id` = a2.`id`) GROUP BY d2.`avatar_id`, d2.`island_id`) AS aux ON (d.`avatar_id` = d2_a_id  AND d.`island_id`=d2_i_id) SET d.`Res_Ges_verb_lag_don` = aux.sum_rg_verb_lag + aux.res_ges_don_ant;
UPDATE donation2 d INNER JOIN ( SELECT Don_Ges AS Don_ges_DA, c2.island_id AS c2_isl_id, d2.avatar_id AS d2_a_id, d2.island_id AS d2_isl_id FROM donation2 d2 INNER JOIN city2 c2 ON (c2.island_id = d2.island_id AND c2.owner_id = d2.avatar_id) GROUP BY d2.island_id, d2.avatar_id) AS donations_amount ON (d.island_id = c2_isl_id AND d.avatar_id = d2_a_id) INNER JOIN (SELECT Rathauslev AS donations_ges, d3.island_id AS d3_isl_id, d3.avatar_id AS d3_a_id FROM donation2 d3 INNER JOIN city2 c3 ON (c3.island_id = d3.island_id AND c3.owner_id=d3.avatar_id) WHERE Rathauslev  !=0) AS buildings_amount ON (d.island_id = d3_isl_id) SET d.Don_pro_Rathauslev = (CASE WHEN donations_amount.Don_ges_DA > 0 THEN (donations_amount.Don_ges_DA / buildings_amount.donations_ges) ELSE 0 END) WHERE donations_amount.d2_a_id = d.avatar_id AND donations_amount.d2_isl_id = d.island_id  AND buildings_amount.d3_a_id = d.avatar_id AND buildings_amount.d3_isl_id = d.island_id;
UPDATE donation2 d INNER JOIN ( SELECT DonH_Luxusminen_Ges AS DonH_Luxusminen_DA, c2.island_id AS c2_isl_id, d2.avatar_id AS d2_a_id, d2.island_id AS d2_isl_id FROM donation2 d2 INNER JOIN city2 c2 ON (c2.island_id = d2.island_id AND c2.owner_id = d2.avatar_id) GROUP BY d2.island_id, d2.avatar_id) AS donations_amount ON (d.island_id = c2_isl_id AND d.avatar_id = d2_a_id) INNER JOIN (SELECT (CASE WHEN tradegood_workers = 0 THEN 1 ELSE tradegood_workers END) AS Dluxusminen_ges, d3.island_id AS d3_isl_id, d3.avatar_id AS d3_a_id FROM donation2 d3 INNER JOIN city2 c3 ON (c3.island_id = d3.island_id AND c3.owner_id=d3.avatar_id) WHERE (CASE WHEN tradegood_workers = 0 THEN 1 ELSE tradegood_workers END)  !=0) AS buildings_amount ON (d.island_id = d3_isl_id) SET d.Don_pro_Tradegood_Worker = (CASE WHEN donations_amount.DonH_Luxusminen_DA > 0 THEN (donations_amount.DonH_Luxusminen_DA / buildings_amount.Dluxusminen_ges) ELSE 0 END) WHERE donations_amount.d2_a_id = d.avatar_id AND donations_amount.d2_isl_id = d.island_id  AND buildings_amount.d3_a_id = d.avatar_id AND buildings_amount.d3_isl_id = d.island_id;
UPDATE donation2 d INNER JOIN ( SELECT Don_Saegewerk_Ges AS Don_Saegewerk_DA, c2.island_id AS c2_isl_id, d2.avatar_id AS d2_a_id, d2.island_id AS d2_isl_id FROM donation2 d2 INNER JOIN city2 c2 ON (c2.island_id = d2.island_id AND c2.owner_id = d2.avatar_id) GROUP BY d2.island_id, d2.avatar_id) AS donations_amount ON (d.island_id = c2_isl_id AND d.avatar_id = d2_a_id) INNER JOIN (SELECT (CASE WHEN resource_workers = 0 THEN 1 ELSE resource_workers END) AS Dsaegewerk_ges, d3.island_id AS d3_isl_id, d3.avatar_id AS d3_a_id FROM donation2 d3 INNER JOIN city2 c3 ON (c3.island_id = d3.island_id AND c3.owner_id=d3.avatar_id) WHERE (CASE WHEN resource_workers = 0 THEN 1 ELSE resource_workers END)  !=0) AS buildings_amount ON (d.island_id = d3_isl_id) SET d.Don_pro_Resource_Worker = (CASE WHEN donations_amount.Don_Saegewerk_DA > 0 THEN (donations_amount.Don_Saegewerk_DA / buildings_amount.Dsaegewerk_ges) ELSE 0 END) WHERE donations_amount.d2_a_id = d.avatar_id AND donations_amount.d2_isl_id = d.island_id  AND buildings_amount.d3_a_id = d.avatar_id AND buildings_amount.d3_isl_id = d.island_id;
UPDATE donation2 d INNER JOIN ( SELECT Don_Wonder_Ges AS Don_Wonder_DA, c2.island_id AS c2_isl_id, d2.avatar_id AS d2_a_id, d2.island_id AS d2_isl_id FROM donation2 d2 INNER JOIN city2 c2 ON (c2.island_id = d2.island_id AND c2.owner_id = d2.avatar_id) GROUP BY d2.island_id, d2.avatar_id) AS donations_amount ON (d.island_id = c2_isl_id AND d.avatar_id = d2_a_id) INNER JOIN (SELECT (CASE WHEN priests = 0 THEN 1 ELSE priests END) AS Dwonder_ges, d3.island_id AS d3_isl_id, d3.avatar_id AS d3_a_id FROM donation2 d3 INNER JOIN city2 c3 ON (c3.island_id = d3.island_id AND c3.owner_id=d3.avatar_id) WHERE (CASE WHEN priests = 0 THEN 1 ELSE priests END)  !=0) AS buildings_amount ON (d.island_id = d3_isl_id) SET d.Don_pro_Priester = (CASE WHEN donations_amount.Don_Wonder_DA > 0 THEN (donations_amount.Don_Wonder_DA / buildings_amount.Dwonder_ges) ELSE 0 END) WHERE donations_amount.d2_a_id = d.avatar_id AND donations_amount.d2_isl_id = d.island_id  AND buildings_amount.d3_a_id = d.avatar_id AND buildings_amount.d3_isl_id = d.island_id;
UPDATE donation2 d INNER JOIN ( SELECT Don_Ges AS res_ges_don, c2.island_id AS c2_isl_id, d2.avatar_id AS d2_a_id, d2.island_id AS d2_isl_id FROM donation2 d2 INNER JOIN city2 c2 ON (c2.island_id = d2.island_id AND c2.owner_id = d2.avatar_id) GROUP BY d2.island_id, d2.avatar_id) AS donations_amount ON (d.island_id = c2_isl_id AND d.avatar_id = d2_a_id) INNER JOIN (SELECT (CASE WHEN Buerger_Ges = 0 THEN 1 ELSE Buerger_Ges END) AS res_ges, d3.island_id AS d3_isl_id, d3.avatar_id AS d3_a_id FROM donation2 d3 INNER JOIN city2 c3 ON (c3.island_id = d3.island_id AND c3.owner_id=d3.avatar_id) WHERE (CASE WHEN Buerger_Ges = 0 THEN 1 ELSE Buerger_Ges END)  !=0) AS buildings_amount ON (d.island_id = d3_isl_id) SET d.Don_pro_Buerger_Ges = (CASE WHEN donations_amount.res_ges_don > 0 THEN (donations_amount.res_ges_don / buildings_amount.res_ges) ELSE 0 END) WHERE donations_amount.d2_a_id = d.avatar_id AND donations_amount.d2_isl_id = d.island_id  AND buildings_amount.d3_a_id = d.avatar_id AND buildings_amount.d3_isl_id = d.island_id;
UPDATE donation2 d INNER JOIN ( SELECT Don_Wonder_Anteil_Schwefel AS Schwefel_don, Schwefel_Ges_verb_lag_don AS Schwefel_ges, d2.island_id AS d2_island_id, d2.avatar_id AS d2_avatar_id FROM donation2 d2 )   AS don ON (d2_island_id = d.island_id AND d2_avatar_id = d.avatar_id)  SET d.Proz_Don_Anteil_Schwefel_von_Schwefel_Ges_verb_lag = (CASE WHEN Schwefel_ges > 0 THEN ((Schwefel_don / Schwefel_ges) * 100) ELSE 0 END) ;
UPDATE donation2 d INNER JOIN ( SELECT Don_Ges AS res_ges_don, Res_Ges_verb_lag_don AS Res_ges, d2.island_id AS d2_island_id, d2.avatar_id AS d2_avatar_id FROM donation2 d2 )   AS don ON (d2_island_id = d.island_id AND d2_avatar_id = d.avatar_id)  SET d.Proz_Don_von_Res_Ges = (CASE WHEN Res_ges > 0 THEN ((Res_Ges_don / Res_Ges) * 100) ELSE 0 END) ;
UPDATE donation2 d INNER JOIN ( SELECT Don_Wonder_Anteil_Stein AS Stein_don, Stein_Ges_verb_lag_don AS Stein_ges, d2.island_id AS d2_island_id, d2.avatar_id AS d2_avatar_id FROM donation2 d2 )   AS don ON (d2_island_id = d.island_id AND d2_avatar_id = d.avatar_id)  SET d.Proz_Don_Anteil_Stein_von_Stein_Ges_verb_lag = (CASE WHEN Stein_ges > 0 THEN ((Stein_don / Stein_ges) * 100) ELSE 0 END) ;
UPDATE donation2 d INNER JOIN ( SELECT Don_Wonder_Anteil_Kristall AS Kristall_don, Kristall_Ges_verb_lag_don AS Kristall_ges, d2.island_id AS d2_island_id, d2.avatar_id AS d2_avatar_id FROM donation2 d2 )   AS don ON (d2_island_id = d.island_id AND d2_avatar_id = d.avatar_id)  SET d.Proz_Don_Anteil_Kristall_von_Kristall_Ges_verb_lag = (CASE WHEN Kristall_ges > 0 THEN ((Kristall_don / Kristall_ges) * 100) ELSE 0 END) ;
UPDATE donation2 d INNER JOIN ( SELECT Don_Wonder_Anteil_Wein AS Wein_don, Wein_Ges_verb_lag_don AS Wein_ges, d2.island_id AS d2_island_id, d2.avatar_id AS d2_avatar_id FROM donation2 d2 )   AS don ON (d2_island_id = d.island_id AND d2_avatar_id = d.avatar_id)  SET d.Proz_Don_Anteil_Wein_von_Wein_Ges_verb_lag = (CASE WHEN Wein_ges > 0 THEN ((Wein_don / Wein_ges) * 100) ELSE 0 END) ;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Saegewerk_Ges + DonH_Luxusminen_Ges) AS holz_don, Holz_Ges_verb_lag_don AS Holz_ges, d2.island_id AS d2_island_id, d2.avatar_id AS d2_avatar_id FROM donation2 d2 )   AS don ON (d2_island_id = d.island_id AND d2_avatar_id = d.avatar_id)  SET d.Proz_Don_Anteil_Holz_von_Holz_Ges_verb_lag = (CASE WHEN Holz_ges > 0 THEN ((Holz_don / Holz_ges) * 100) ELSE 0 END) ;
UPDATE donation2 d INNER JOIN ( SELECT SUM(Don_Saegewerk_Ges + DonH_Luxusminen_Ges)  DonH_Ges, avatar_id d_avatar_id,  island_id d_island_id FROM donation2 GROUP BY avatar_id, island_id) AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`DonH_Ges` = don.`DonH_Ges`;
UPDATE donation2 d INNER JOIN ( SELECT SUM((Proz_Don_Anteil_Stein_von_Stein_Ges_verb_lag + Proz_Don_Anteil_Wein_von_Wein_Ges_verb_lag + Proz_Don_Anteil_Kristall_von_Kristall_Ges_verb_lag + Proz_Don_Anteil_Schwefel_von_Schwefel_Ges_verb_lag/4))  Proz_Don_Lux_Ges, avatar_id d_avatar_id,  island_id d_island_id FROM donation2 GROUP BY avatar_id, island_id) AS don ON d.avatar_id = don.d_avatar_id AND d.island_id = don.d_island_id SET d.`Proz_DonH_Lux_Ges` = don.`Proz_Don_Lux_Ges`;
UPDATE donation2 d INNER JOIN ( SELECT DonH_Luxusminen_Ges AS Luxusminen_don, Holz_Ges_verb_lag_don AS Holz_ges, d2.island_id AS d2_island_id, d2.avatar_id AS d2_avatar_id FROM donation2 d2 )   AS don ON (d2_island_id = d.island_id AND d2_avatar_id = d.avatar_id)  SET d.Proz_DonH_Lux_Ges = (CASE WHEN Holz_ges > 0 THEN ((Luxusminen_don / Holz_ges) * 100) ELSE 0 END);

