# Q28_Delete_Players

#ACHTUNG: Wieviele Zeilen sind von Löschung betroffen notieren für Paper; 
# Die Zeit = vor frühestem Startzeitpunkt jedes Servers
# de,en,fr,gr,tr = Startzeit 25.4.2013 10:00:00 = 1366797600

DELETE a.*, c.*, d.* FROM city2 c LEFT OUTER JOIN avatar a ON a.id = c.owner_id LEFT OUTER JOIN donation2 d ON a.id = d.avatar_id INNER JOIN teilnahme_av t ON t.id = c.owner_id WHERE a.`registration_time` < '1366797600';

# Q29_Delete_Donations_without_city

DELETE d.* FROM donation2 d LEFT OUTER JOIN city2 c ON d.avatar_id = c.owner_id AND d.island_id = c.island_id WHERE c.id IS NULL;

# Q30_Update_Island_Calc

UPDATE island i INNER JOIN (SELECT COUNT(id) Anz_Staedte,island_id FROM city2 GROUP BY island_id) AS cit ON i.id = cit.island_id SET Anz_Staedte_pro_Insel = cit.Anz_Staedte;
UPDATE island SET `DonH_Luxusminen_noetig_Durchschnitt` = (Sub_noetig_nextlev_tradegood / (CASE WHEN Anz_Staedte_pro_Insel = 0 THEN 1 ELSE Anz_Staedte_pro_Insel END)) ;
UPDATE island SET `Don_Wonder_noetig_Durchschnitt` = (Sub_noetig_nextlev_wonder / (CASE WHEN Anz_Staedte_pro_Insel = 0 THEN 1 ELSE Anz_Staedte_pro_Insel END)) ;
UPDATE island SET `Don_Saegewerk_noetig_Durchschnitt` = (Sub_noetig_nextlev_resource / (CASE WHEN Anz_Staedte_pro_Insel = 0 THEN 1 ELSE Anz_Staedte_pro_Insel END)) ;

SELECT @sum_resource_level_db:= SUM(`resource_level`) FROM island;
SELECT @sum_tradegood_level_db:= SUM(`tradegood_level`) FROM island;
SELECT @sum_wonder_level_db:= SUM(`wonder_level`) FROM island;
SELECT @sum_avatare_per_db:= COUNT(`id`) FROM avatar;
SELECT @sum_besied_inseln_per_db:= COUNT(`id`) FROM island WHERE Anz_Staedte_pro_Insel > 0;
SELECT @sum_staedte_per_db:= COUNT(`id`) FROM city2;

UPDATE island SET `Anz_Inseln_per_DB` = @sum_besied_inseln_per_db;
UPDATE island SET `Avg_Resource_lev_per_Av` = @sum_resource_level_db / @sum_avatare_per_db;
UPDATE island SET `Avg_Tradegood_lev_per_Av` = @sum_tradegood_level_db / @sum_avatare_per_db;
UPDATE island SET `Avg_Wonder_lev_per_Av` = @sum_wonder_level_db / @sum_avatare_per_db;
UPDATE island SET `Resource_level_pro_Anz_Spieler_DB` = @sum_resource_level_db / @sum_avatare_per_db;
UPDATE island SET `tradegood_level_pro_Anz_Spieler_DB` = @sum_tradegood_level_db / @sum_avatare_per_db;
UPDATE island SET `wonder_level_pro_Anz_Spieler_DB` = @sum_wonder_level_db / @sum_avatare_per_db;
UPDATE island SET `Resource_level_pro_Anz_Inseln_DB` = @sum_resource_level_db / @sum_besied_inseln_per_db;
UPDATE island SET `tradegood_level_pro_Anz_Inseln_DB` = @sum_tradegood_level_db / @sum_besied_inseln_per_db;
UPDATE island SET `wonder_level_pro_Anz_Inseln_DB` = @sum_wonder_level_db / @sum_besied_inseln_per_db;
UPDATE island SET `resource_level_pro_Anz_Staedte_DB` = @sum_resource_level_db / @sum_staedte_per_db;
UPDATE island SET `tradegood_level_pro_Anz_Staedte_DB` = @sum_tradegood_level_db / @sum_staedte_per_db;
UPDATE island SET `wonder_level_pro_Anz_Staedte_DB` = @sum_wonder_level_db / @sum_staedte_per_db;

# Q31_Update_Avatar_Calc

SELECT @avg_spieldauer := AVG(`spieldauer`) FROM avatar;

UPDATE avatar a INNER JOIN ( SELECT COUNT(`id`)  Anz_Av_per_DB FROM avatar) AS av SET a.`Anz_Av_per_DB` = av.`Anz_Av_per_DB`;
UPDATE avatar SET `Avg_Spieldauer` = @avg_spieldauer;

# Q32_Update_City2_AVG_Count_nachher

UPDATE city2 c INNER JOIN ( SELECT COUNT(`island_id`)  Anz_Ins_per_Av, owner_id c_owner_id FROM city2 GROUP BY owner_id) AS ci ON c.owner_id = ci.c_owner_id SET c.`Anz_Ins_per_Av` = ci.`Anz_Ins_per_Av`;
UPDATE city2 c INNER JOIN ( SELECT COUNT(`id`)  Anz_cities_per_Av, owner_id c_owner_id FROM city2 GROUP BY owner_id) AS ci ON c.owner_id = ci.c_owner_id SET c.`Anz_cities_per_Av` = ci.`Anz_cities_per_Av`;
UPDATE city2 c INNER JOIN ( SELECT COUNT(`owner_id`)  Anz_cities_per_DB FROM city2) AS ci SET c.`Anz_cities_per_DB` = ci.`Anz_cities_per_DB`;
UPDATE city2 c SET Proz_resource_workers_pro_Buerger_Ges =((resource_workers /(CASE WHEN Buerger_Ges = '0'  THEN 1 ELSE Buerger_Ges END))*100);
UPDATE city2 c SET Proz_tradegood_workers_pro_Buerger_Ges = ((tradegood_workers /(CASE WHEN Buerger_Ges = '0'  THEN 1 ELSE Buerger_Ges END))*100);

# Q33_Update_Donation2_Calc

SELECT @Sum_Don_Ges_DB:= SUM(`Don_Ges`) FROM donation2;
SELECT @Sum_DonH_Ges_DB:= SUM(`DonH_Ges`) FROM donation2;
SELECT @Sum_Don_Wonder_Ges_DB:= SUM(`Don_Wonder_Ges`) FROM donation2;
SELECT @Sum_DonH_Luxusminen_Ges_DB:= SUM(`DonH_Luxusminen_Ges`) FROM donation2;
SELECT @Spieldauer_Ges_DB:= SUM(`Spieldauer`) FROM avatar;
SELECT @Sum_Anz_Inseln_per_DB:= (SELECT COUNT(id) FROM island WHERE Anz_Staedte_pro_Insel > 0);
SELECT @Sum_Anz_Av_per_DB:= (SELECT COUNT(*) FROM avatar);
SELECT @Sum_Anz_Cities_per_DB:= (SELECT COUNT(id) FROM city2);

UPDATE donation2 d INNER JOIN ( SELECT Don_Ges AS Don_ges_DA, c2.island_id AS c2_isl_id, d2.avatar_id AS d2_a_id, d2.island_id AS d2_isl_id FROM donation2 d2 INNER JOIN city2 c2 ON (c2.island_id = d2.island_id AND c2.owner_id = d2.avatar_id) GROUP BY d2.island_id, d2.avatar_id) AS donations_amount ON (d.island_id = c2_isl_id AND d.avatar_id = d2_a_id) INNER JOIN (SELECT Anz_Cities_per_Av AS donations_ges, d3.island_id AS d3_isl_id, d3.avatar_id AS d3_a_id FROM donation2 d3 INNER JOIN city2 c3 ON (c3.island_id = d3.island_id AND c3.owner_id=d3.avatar_id) WHERE Anz_Cities_per_Av  !=0) AS buildings_amount ON (d.island_id = d3_isl_id) SET d.Don_pro_City = (CASE WHEN donations_amount.Don_ges_DA > 0 THEN (donations_amount.Don_ges_DA / buildings_amount.donations_ges) ELSE 0 END) WHERE donations_amount.d2_a_id = d.avatar_id AND donations_amount.d2_isl_id = d.island_id  AND buildings_amount.d3_a_id = d.avatar_id AND buildings_amount.d3_isl_id = d.island_id;
UPDATE donation2 d INNER JOIN ( SELECT SUM(`Don_Ges`)  AS Don_pro_DB FROM donation2) AS don SET d.`Don_pro_DB` = don.`Don_pro_DB`;
UPDATE donation2 d SET d.Don_Ges_pro_Anz_Inseln_DB = (@sum_don_ges_db  / @Sum_Anz_Inseln_per_DB);
UPDATE donation2 d SET d.Don_Ges_pro_Anz_Spieler_DB = (@sum_don_ges_db  / @Sum_Anz_Av_per_DB);
UPDATE donation2 d SET d.Don_Ges_pro_Anz_Staedte_DB = (@sum_don_ges_db  / @Sum_Anz_Cities_per_DB);
UPDATE donation2 d SET d.DonH_Ges_pro_Anz_Inseln_DB = (@sum_donh_ges_db  / @Sum_Anz_Inseln_per_DB);
UPDATE donation2 d SET d.DonH_Ges_pro_Anz_Spieler_DB = (@sum_donh_ges_db  / @Sum_Anz_Av_per_DB);
UPDATE donation2 d SET d.DonH_Ges_pro_Anz_Staedte_DB = (@sum_donh_ges_db  / @Sum_Anz_Cities_per_DB);
UPDATE donation2 d SET d.Don_Wonder_Ges_pro_Anz_Inseln_DB = (@Sum_Don_Wonder_Ges_DB  / @Sum_Anz_Inseln_per_DB);
UPDATE donation2 d SET d.Don_Wonder_Ges_pro_Anz_Spieler_DB = (@Sum_Don_Wonder_Ges_DB  / @Sum_Anz_Av_per_DB);
UPDATE donation2 d SET d.Don_Wonder_Ges_pro_Anz_Staedte_DB = (@Sum_Don_Wonder_Ges_DB  / @Sum_Anz_Cities_per_DB);
UPDATE donation2 d SET d.DonH_Luxusminen_Ges_pro_Anz_Inseln_DB = (@Sum_DonH_Luxusminen_Ges_DB  / @Sum_Anz_Inseln_per_DB);
UPDATE donation2 d SET d.DonH_Luxusminen_Ges_pro_Anz_Spieler_DB = (@Sum_DonH_Luxusminen_Ges_DB  / @Sum_Anz_Av_per_DB);
UPDATE donation2 d SET d.DonH_Luxusminen_Ges_pro_Anz_Staedte_DB = (@Sum_DonH_Luxusminen_Ges_DB  / @Sum_Anz_Cities_per_DB);
UPDATE donation2 d SET Don_Ges_pro_Spieldauer_Ges_DB = (@sum_don_ges_db  / @Spieldauer_Ges_DB);
UPDATE donation2 d SET Don_Ges_pro_Spieldauer_Ges_DB = (@sum_don_ges_db  / @Spieldauer_Ges_DB);
UPDATE donation2 d INNER JOIN ( SELECT SUM(Don_Saegewerk_Ges)  Don_Saegewerk_Ges_pro_Insel, island_id d_island_id FROM donation2 GROUP BY island_id) AS don ON d.island_id = don.d_island_id SET d.`Don_Saegewerk_Ges_pro_Insel` = don.`Don_Saegewerk_Ges_pro_Insel`;
UPDATE donation2 d INNER JOIN ( SELECT SUM(Don_Ges)  Don_Ges_pro_Insel, island_id d_island_id FROM donation2 GROUP BY island_id) AS don ON d.island_id = don.d_island_id SET d.`Don_Ges_pro_Insel` = don.`Don_Ges_pro_Insel`;
UPDATE donation2 d INNER JOIN ( SELECT SUM(DonH_Ges)  DonH_Ges_pro_Insel, island_id d_island_id FROM donation2 GROUP BY island_id) AS don ON d.island_id = don.d_island_id SET d.`DonH_Ges_pro_Insel` = don.`DonH_Ges_pro_Insel`;
UPDATE donation2 d INNER JOIN ( SELECT SUM(DonH_Luxusminen_Ges)  DonH_Luxusminen_Ges_pro_Insel, island_id d_island_id FROM donation2 GROUP BY island_id) AS don ON d.island_id = don.d_island_id SET d.`DonH_Luxusminen_Ges_pro_Insel` = don.`DonH_Luxusminen_Ges_pro_Insel`;
UPDATE donation2 d INNER JOIN ( SELECT SUM(Don_Wonder_Ges)  Don_Wonder_Ges_pro_Insel, island_id d_island_id FROM donation2 GROUP BY island_id) AS don ON d.island_id = don.d_island_id SET d.`Don_Wonder_Ges_pro_Insel` = don.`Don_Wonder_Ges_pro_Insel`;
UPDATE donation2 d INNER JOIN ( SELECT ((Don_Saegewerk_Ges_pro_Insel-Don_Saegewerk_Ges) /(Anz_Staedte_pro_Insel - 1)) Avg_Don_Saegewerk_Ges_ohne_Av, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Avg_Don_Saegewerk_Ges_ohne_Av` = don.`Avg_Don_Saegewerk_Ges_ohne_Av`;
UPDATE donation2 d INNER JOIN ( SELECT ((Don_Ges_pro_Insel-Don_Ges) /(Anz_Staedte_pro_Insel - 1)) Avg_Don_Ges_ohne_Av, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Avg_Don_Ges_ohne_Av` = don.`Avg_Don_Ges_ohne_Av`;
UPDATE donation2 d INNER JOIN ( SELECT ((DonH_Ges_pro_Insel-DonH_Ges) /(Anz_Staedte_pro_Insel - 1)) Avg_DonH_Ges_ohne_Av, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Avg_DonH_Ges_ohne_Av` = don.`Avg_DonH_Ges_ohne_Av`;
UPDATE donation2 d INNER JOIN ( SELECT ((DonH_Luxusminen_Ges_pro_Insel-DonH_Luxusminen_Ges) /(Anz_Staedte_pro_Insel - 1)) Avg_DonH_Luxusminen_Ges_ohne_Av, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Avg_DonH_Luxusminen_Ges_ohne_Av` = don.`Avg_DonH_Luxusminen_Ges_ohne_Av`;
UPDATE donation2 d INNER JOIN ( SELECT ((Don_Wonder_Ges_pro_Insel-Don_Wonder_Ges) /(Anz_Staedte_pro_Insel - 1)) Avg_Don_Wonder_Ges_ohne_Av, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Avg_Don_Wonder_Ges_ohne_Av` = don.`Avg_Don_Wonder_Ges_ohne_Av`;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Saegewerk_Ges-Avg_Don_Saegewerk_Ges_ohne_Av) AS Diff_Av_Don_Saegewerk_Ges_zu_Avg, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Diff_Av_Don_Saegewerk_Ges_zu_Avg` = don.`Diff_Av_Don_Saegewerk_Ges_zu_Avg`;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Ges-Avg_Don_Ges_ohne_Av) AS Diff_Av_Don_Ges_zu_Avg, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Diff_Av_Don_Ges_zu_Avg` = don.`Diff_Av_Don_Ges_zu_Avg`;
UPDATE donation2 d INNER JOIN ( SELECT (DonH_Ges-Avg_DonH_Ges_ohne_Av) AS Diff_Av_DonH_Ges_zu_Avg, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Diff_Av_DonH_Ges_zu_Avg` = don.`Diff_Av_DonH_Ges_zu_Avg`;
UPDATE donation2 d INNER JOIN ( SELECT (DonH_Luxusminen_Ges-Avg_DonH_Luxusminen_Ges_ohne_Av) AS Diff_Av_DonH_Luxusminen_Ges_zu_Avg, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Diff_Av_DonH_Luxusminen_Ges_zu_Avg` = don.`Diff_Av_DonH_Luxusminen_Ges_zu_Avg`;
UPDATE donation2 d INNER JOIN ( SELECT (Don_Wonder_Ges-Avg_Don_Wonder_Ges_ohne_Av) AS Diff_Av_Don_Wonder_Ges_zu_Avg, island_id AS d2_island_id, avatar_id AS d2_avatar_id FROM donation2 d2 INNER JOIN island i ON d2.island_id = i.id) AS don ON d.island_id = don.d2_island_id AND d.avatar_id = don.d2_avatar_id SET d.`Diff_Av_Don_Wonder_Ges_zu_Avg` = don.`Diff_Av_Don_Wonder_Ges_zu_Avg`;
UPDATE donation2 d INNER JOIN ( SELECT COUNT(`avatar_id`)  Anz_Don_per_DB FROM donation2  WHERE `gold` <> 0 AND `type` <> 0) AS don  SET d.`Anz_Don_per_DB` = don.`Anz_Don_per_DB`;

UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id, c.island_id,Buerger_Ges FROM avatar a  INNER JOIN city2 c ON a.id = c.owner_id INNER JOIN donation2 d2 ON d2.avatar_id = c.owner_id AND d2.island_id = c.island_id) AS av ON d.avatar_id = av.a_avatar_id AND d.island_id = av.island_id SET d.`Buerger_Ges_pro_Spieldauer` = ((CASE WHEN Buerger_Ges = 0 THEN 1 ELSE Buerger_Ges END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Don_Ges_pro_Spieldauer` = ((CASE WHEN Don_Ges = 0 THEN 1 ELSE Don_Ges END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Don_Saegewerk_Ges_pro_Spieldauer` = ((CASE WHEN Don_Saegewerk_Ges = 0 THEN 1 ELSE Don_Saegewerk_Ges END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Don_Wonder_Ges_pro_Spieldauer` = ((CASE WHEN Don_Wonder_Ges = 0 THEN 1 ELSE Don_Wonder_Ges END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`DonH_Ges_pro_Spieldauer` = ((CASE WHEN DonH_Ges = 0 THEN 1 ELSE DonH_Ges END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`DonH_Luxusminen_Ges_pro_Spieldauer` = ((CASE WHEN DonH_Luxusminen_Ges = 0 THEN 1 ELSE DonH_Luxusminen_Ges END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id, c.island_id,Geblev FROM avatar a  INNER JOIN city2 c ON a.id = c.owner_id INNER JOIN donation2 d2 ON d2.avatar_id = c.owner_id AND d2.island_id = c.island_id) AS av ON d.avatar_id = av.a_avatar_id AND d.island_id = av.island_id SET d.`Geblev_pro_Spieldauer` = ((CASE WHEN Geblev = 0 THEN 1 ELSE Geblev END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Holz_Ges_verb_lag_don_pro_Spieldauer` = ((CASE WHEN Holz_Ges_verb_lag_don = 0 THEN 1 ELSE Holz_Ges_verb_lag_don END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Kristall_Ges_verb_lag_don_pro_Spieldauer` = ((CASE WHEN Kristall_Ges_verb_lag_don = 0 THEN 1 ELSE Kristall_Ges_verb_lag_don END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id, c.island_id,Rathauslev FROM avatar a  INNER JOIN city2 c ON a.id = c.owner_id INNER JOIN donation2 d2 ON d2.avatar_id = c.owner_id AND d2.island_id = c.island_id) AS av ON d.avatar_id = av.a_avatar_id AND d.island_id = av.island_id SET d.`Rathauslev_pro_Spieldauer` = ((CASE WHEN Rathauslev = 0 THEN 1 ELSE Rathauslev END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Res_Ges_verb_lag_don_pro_Spieldauer` = ((CASE WHEN Res_Ges_verb_lag_don = 0 THEN 1 ELSE Res_Ges_verb_lag_don END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id, c.island_id,resource_workers FROM avatar a  INNER JOIN city2 c ON a.id = c.owner_id INNER JOIN donation2 d2 ON d2.avatar_id = c.owner_id AND d2.island_id = c.island_id) AS av ON d.avatar_id = av.a_avatar_id AND d.island_id = av.island_id SET d.`resource_workers_pro_Spieldauer` = ((CASE WHEN resource_workers = 0 THEN 1 ELSE resource_workers END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Schwefel_Ges_verb_lag_don_pro_Spieldauer` = ((CASE WHEN Schwefel_Ges_verb_lag_don = 0 THEN 1 ELSE Schwefel_Ges_verb_lag_don END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Stein_Ges_verb_lag_don_pro_Spieldauer` = ((CASE WHEN Stein_Ges_verb_lag_don = 0 THEN 1 ELSE Stein_Ges_verb_lag_don END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id, c.island_id,tradegood_workers FROM avatar a  INNER JOIN city2 c ON a.id = c.owner_id INNER JOIN donation2 d2 ON d2.avatar_id = c.owner_id AND d2.island_id = c.island_id) AS av ON d.avatar_id = av.a_avatar_id AND d.island_id = av.island_id SET d.`tradegood_workers_pro_Spieldauer` = ((CASE WHEN tradegood_workers = 0 THEN 1 ELSE tradegood_workers END) / Spieldauer);
UPDATE donation2 d INNER JOIN ( SELECT Spieldauer, a.id AS a_avatar_id FROM avatar a ) AS av ON d.avatar_id = av.a_avatar_id SET d.`Wein_Ges_verb_lag_don_pro_Spieldauer` = ((CASE WHEN Wein_Ges_verb_lag_don = 0 THEN 1 ELSE Wein_Ges_verb_lag_don END) / Spieldauer);

UPDATE donation2 d INNER JOIN ( SELECT Don_Saegewerk_Ges, Avg_Don_Saegewerk_Ges_ohne_Av, island_id, avatar_id FROM donation2) AS don ON  d.island_id = don.island_id AND d.avatar_id = don.avatar_id SET d.`Proz_Don_Saegewerk_Ges_von_Avg_Don_SW_ohne_Av` = CASE WHEN (don.Don_Saegewerk_Ges = 0) AND (don.Avg_Don_Saegewerk_Ges_ohne_Av > 0) THEN 0 WHEN (don.Don_Saegewerk_Ges = 0) AND (don.Avg_Don_Saegewerk_Ges_ohne_Av = 0) THEN 100 WHEN (don.Don_Saegewerk_Ges > 0) AND (don.Avg_Don_Saegewerk_Ges_ohne_Av = 0) THEN 0 ELSE ((don.Don_Saegewerk_Ges /  don.Avg_Don_Saegewerk_Ges_ohne_Av) * 100 -100) END;
UPDATE donation2 d INNER JOIN ( SELECT Don_Ges, Avg_Don_Ges_ohne_Av, island_id, avatar_id FROM donation2) AS don ON  d.island_id = don.island_id AND d.avatar_id = don.avatar_id SET d.`Proz_Don_Ges_von_Avg_Don_DG_ohne_Av` = CASE WHEN (don.Don_Ges = 0) AND (don.Avg_Don_Ges_ohne_Av > 0) THEN 0 WHEN (don.Don_Ges = 0) AND (don.Avg_Don_Ges_ohne_Av = 0) THEN 100 WHEN (don.Don_Ges > 0) AND (don.Avg_Don_Ges_ohne_Av = 0) THEN 0 ELSE ((don.Don_Ges /  don.Avg_Don_Ges_ohne_Av) * 100 -100) END;
UPDATE donation2 d INNER JOIN ( SELECT DonH_Ges, Avg_DonH_Ges_ohne_Av, island_id, avatar_id FROM donation2) AS don ON  d.island_id = don.island_id AND d.avatar_id = don.avatar_id SET d.`Proz_DonH_Ges_von_Avg_Don_DHG_ohne_Av` = CASE WHEN (don.DonH_Ges = 0) AND (don.Avg_DonH_Ges_ohne_Av > 0) THEN 0 WHEN (don.DonH_Ges = 0) AND (don.Avg_DonH_Ges_ohne_Av = 0) THEN 100 WHEN (don.DonH_Ges > 0) AND (don.Avg_DonH_Ges_ohne_Av = 0) THEN 0 ELSE ((don.DonH_Ges /  don.Avg_DonH_Ges_ohne_Av) * 100 -100) END;
