UPDATE city4isl c  INNER JOIN (SELECT AVG(`Buerger_Ges`) AS Avg_Buerger_Ges, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Buerger_Ges` = cit.`Avg_Buerger_Ges`;
UPDATE city4isl c  INNER JOIN (SELECT AVG(`Holz_Ges_verb_lag`) AS Avg_Holz_Ges_verb_lag, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Holz_Ges_verb_lag` = cit.`Avg_Holz_Ges_verb_lag`;
