UPDATE city4isl c  INNER JOIN (SELECT AVG(`Rathauslev`) AS Avg_Rathauslev, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Rathauslev` = cit.`Avg_Rathauslev`;
UPDATE city4isl c  INNER JOIN (SELECT AVG(`Res_Ges_verb_lag`) AS Avg_Res_Ges_verb_lag, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Res_Ges_verb_lag` = cit.`Avg_Res_Ges_verb_lag`;
UPDATE city4isl c  INNER JOIN (SELECT AVG(`Resource_workers`) AS Avg_Resource_workers, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Resource_workers` = cit.`Avg_Resource_workers`;
UPDATE city4isl c  INNER JOIN (SELECT AVG(`Schwefel_Ges_verb_lag`) AS Avg_Schwefel_Ges_verb_lag, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Schwefel_Ges_verb_lag` = cit.`Avg_Schwefel_Ges_verb_lag`;
UPDATE city4isl c  INNER JOIN (SELECT AVG(`Stein_Ges_verb_lag`) AS Avg_Stein_Ges_verb_lag, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Stein_Ges_verb_lag` = cit.`Avg_Stein_Ges_verb_lag`;
UPDATE city4isl c  INNER JOIN (SELECT AVG(`Tradegood_workers`) AS Avg_Tradegood_workers, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Tradegood_workers` = cit.`Avg_Tradegood_workers`;
UPDATE city4isl c  INNER JOIN (SELECT AVG(`Wein_Ges_verb_lag`) AS Avg_Wein_Ges_verb_lag, island_id AS c_island_id FROM city2 c2 GROUP BY island_id) AS cit ON c.island_id = cit.c_island_id SET c.`Avg_Wein_Ges_verb_lag` = cit.`Avg_Wein_Ges_verb_lag`;

UPDATE city4isl c INNER JOIN ( SELECT SUM(Resource_workers) AS resworkers, SUM(Buerger_Ges) AS BuergerGes, island_id AS c_island_id FROM city2 c_tmp GROUP BY island_id) AS cit ON c.island_id =cit.c_island_id SET c.`Proz_resource_workers_pro_Buerger_Ges` = (CASE WHEN (cit.`resworkers` > 0 AND  cit.`BuergerGes` > 0) THEN ((cit.`resworkers` / cit.`BuergerGes`) * 100) ELSE 0 END);
UPDATE city4isl c INNER JOIN ( SELECT SUM(Tradegood_workers) AS tradworkers, SUM(Buerger_Ges) AS BuergerGes, island_id AS c_island_id FROM city2 c_tmp GROUP BY island_id) AS cit ON c.island_id =cit.c_island_id SET c.`Proz_tradegood_workers_pro_Buerger_Ges` = (CASE WHEN (cit.`tradworkers` > 0 AND  cit.`BuergerGes` > 0) THEN ((cit.`tradworkers` / cit.`BuergerGes`) * 100) ELSE 0 END);

