# Q39_UPDATE_donation3Av_Pro_u_Proz_nachher

UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Ges) AS   Don_ges_DA, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT SUM(`Rathauslev`) AS Sum_Rathauslev, owner_id AS c2_owner_id   FROM city2 c_tmp GROUP BY owner_id) AS aux_cit ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_cit.`c2_owner_id`) SET d.`Don_pro_Rathauslev` = (CASE WHEN don.`Don_ges_DA` > 0 THEN (don.`Don_ges_DA` / aux_cit.`Sum_Rathauslev`) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Ges) AS   Don_ges_DA, avatar_id AS d_avatar_id FROM donation2 d_tmp INNER JOIN city2 ON d_tmp.avatar_id = city2.owner_id GROUP BY avatar_id) AS don INNER JOIN (SELECT SUM(`Anz_Cities_per_Av`) AS Sum_Anz_Cities_per_Av, owner_id AS c2_owner_id   FROM city2 c_tmp GROUP BY owner_id) AS aux_cit ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_cit.`c2_owner_id`) SET d.`Don_pro_City` = (CASE WHEN don.`Don_ges_DA` > 0 THEN (don.`Don_ges_DA` / aux_cit.`Sum_Anz_Cities_per_Av`) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(DonH_Luxusminen_Ges) AS   DonH_Luxusminen_DA, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT SUM((CASE WHEN tradegood_workers = 0 THEN 1 ELSE tradegood_workers END)) AS Sum_tradegood_workers, owner_id AS c2_owner_id   FROM city2 c_tmp INNER JOIN donation2 don2 ON c_tmp.island_id = don2.island_id AND c_tmp.owner_id = don2.avatar_id GROUP BY owner_id) AS aux_cit ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_cit.`c2_owner_id`) SET d.`Don_pro_Tradegood_Worker` = (CASE WHEN don.`DonH_Luxusminen_DA` > 0 THEN (don.`DonH_Luxusminen_DA` / aux_cit.`Sum_tradegood_workers`) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Saegewerk_Ges) AS   Don_Saegewerk_DA, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT SUM((CASE WHEN resource_workers = 0 THEN 1 ELSE resource_workers END)) AS Sum_resource_workers, owner_id AS c2_owner_id   FROM city2 c_tmp INNER JOIN donation2 don2 ON c_tmp.island_id = don2.island_id AND c_tmp.owner_id = don2.avatar_id GROUP BY owner_id) AS aux_cit ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_cit.`c2_owner_id`) SET d.`Don_pro_Resource_Worker` = (CASE WHEN don.`Don_Saegewerk_DA` > 0 THEN (don.`Don_Saegewerk_DA` / aux_cit.`Sum_resource_workers`) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Wonder_Ges) AS   Don_Wonder_DA, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT SUM((CASE WHEN priests = 0 THEN 1 ELSE priests END)) AS Sum_priests, owner_id AS c2_owner_id   FROM city2 c_tmp INNER JOIN donation2 don2 ON c_tmp.island_id = don2.island_id AND c_tmp.owner_id = don2.avatar_id GROUP BY owner_id) AS aux_cit ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_cit.`c2_owner_id`) SET d.`Don_pro_Priester` = (CASE WHEN don.`Don_Wonder_DA` > 0 THEN (don.`Don_Wonder_DA` / aux_cit.`Sum_priests`) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Wonder_Anteil_Schwefel) AS   schwefel_don, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT (`Schwefel_Ges_verb_lag_don`) AS Sum_schwefel_don, avatar_id AS d2_avatar_id FROM donation3a d2 GROUP BY avatar_id) AS aux_don ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_don.`d2_avatar_id`) SET d.`Proz_Don_Anteil_Schwefel_von_Schwefel_Ges_verb_lag` = (CASE WHEN (don.`schwefel_don` > 0 AND  aux_don.`Sum_schwefel_don` > 0) THEN ((don.`schwefel_don` / aux_don.`Sum_schwefel_don`) * 100) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Ges) AS   res_ges_don, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT (`Res_Ges_verb_lag_don`) AS Sum_res_ges_don, avatar_id AS d2_avatar_id FROM donation3a d2 GROUP BY avatar_id) AS aux_don ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_don.`d2_avatar_id`) SET d.`Proz_Don_von_Res_Ges` = (CASE WHEN (don.`res_ges_don` > 0 AND  aux_don.`Sum_res_ges_don` > 0) THEN ((don.`res_ges_don` / aux_don.`Sum_res_ges_don`) * 100) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Wonder_Anteil_Stein) AS   stein_don, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT (`Stein_Ges_verb_lag_don`) AS Sum_Stein_Ges_don, avatar_id AS d2_avatar_id FROM donation3a d2 GROUP BY avatar_id) AS aux_don ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_don.`d2_avatar_id`) SET d.`Proz_Don_Anteil_Stein_von_Stein_Ges_verb_lag` = (CASE WHEN (don.`stein_don` > 0 AND  aux_don.`Sum_Stein_Ges_don` > 0) THEN ((don.`stein_don` / aux_don.`Sum_Stein_Ges_don`) * 100) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Wonder_Anteil_Kristall) AS   kristall_don, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT (`Kristall_Ges_verb_lag_don`) AS Sum_Kristall_Ges_don, avatar_id AS d2_avatar_id FROM donation3a d2 GROUP BY avatar_id) AS aux_don ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_don.`d2_avatar_id`) SET d.`Proz_Don_Anteil_Kristall_von_Kristall_Ges_verb_lag` = (CASE WHEN (don.`kristall_don` > 0 AND  aux_don.`Sum_Kristall_Ges_don` > 0) THEN ((don.`kristall_don` / aux_don.`Sum_Kristall_Ges_don`) * 100) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Wonder_Anteil_Wein) AS   wein_don, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT (`Wein_Ges_verb_lag_don`) AS Sum_Wein_Ges_don, avatar_id AS d2_avatar_id FROM donation3a d2 GROUP BY avatar_id) AS aux_don ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_don.`d2_avatar_id`) SET d.`Proz_Don_Anteil_Wein_von_Wein_Ges_verb_lag` = (CASE WHEN (don.`wein_don` > 0 AND  aux_don.`Sum_Wein_Ges_don` > 0) THEN ((don.`wein_don` / aux_don.`Sum_Wein_Ges_don`) * 100) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(DonH_Ges) AS   holz_don, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don INNER JOIN (SELECT (`Holz_Ges_verb_lag_don`) AS Sum_Holz_Ges_don, avatar_id AS d2_avatar_id FROM donation3a d2 GROUP BY avatar_id) AS aux_don ON ( d.`avatar_id` = don.`d_avatar_id` AND d.`avatar_id` = aux_don.`d2_avatar_id`) SET d.`Proz_Don_Anteil_Holz_von_Holz_Ges_verb_lag` = (CASE WHEN (don.`holz_don` > 0 AND  aux_don.`Sum_Holz_Ges_don` > 0) THEN ((don.`holz_don` / aux_don.`Sum_Holz_Ges_don`) * 100) ELSE 0 END);

UPDATE donation3av d INNER JOIN ( SELECT SUM(DonH_Luxusminen_Ges) AS donhluxges, SUM(`Holz_Ges_verb_lag_don`) AS holzgesverblagdon, avatar_id AS d_avatar_id FROM donation2 d_tmp GROUP BY avatar_id) AS don ON ( d.`avatar_id` = don.`d_avatar_id`) SET d.`Proz_DonH_Lux_Ges` = (CASE WHEN (don.`donhluxges` > 0 AND  don.`holzgesverblagdon` > 0) THEN ((don.`donhluxges` / don.`holzgesverblagdon`) * 100) ELSE 0 END);
UPDATE donation3av d INNER JOIN ( SELECT SUM(Don_Ges) AS Don_Ges, SUM(`Buerger_Ges`) AS Buerger_Ges, avatar_id AS d_avatar_id FROM donation2 d_tmp INNER JOIN city2 c ON (`owner_id` = `avatar_id` AND c.`island_id` = d_tmp.`island_id`) GROUP BY avatar_id) AS don ON ( d.`avatar_id` = don.`d_avatar_id`) SET d.`Don_pro_Buerger_Ges` = (CASE WHEN (don.`Don_Ges` > 0 AND  don.`Buerger_Ges` > 0) THEN (don.`Don_Ges` / don.`Buerger_Ges`) ELSE 0 END);
