CREATE TABLE donation4isl AS SELECT * FROM donation4i GROUP BY island_id;
ALTER TABLE donation4isl ADD PRIMARY KEY (`island_id`);

# Q42_UPDATE_Donation_4Isl_ProProz_nachher

UPDATE donation4isl d INNER JOIN ( SELECT SUM(Don_Ges) AS   Don_ges_DA, island_id AS d_island_id FROM donation2 d_tmp GROUP BY island_id) AS don INNER JOIN (SELECT SUM(`Rathauslev`) AS Sum_Rathauslev, island_id AS c2_island_id FROM city2 c GROUP BY island_id) AS aux_cit ON ( d.`island_id` = don.`d_island_id` AND d.`island_id` = aux_cit.`c2_island_id`) SET d.`Don_pro_Rathauslev` = (CASE WHEN (don.`Don_ges_DA` > 0) THEN (don.`Don_ges_DA` / aux_cit.`Sum_Rathauslev`) ELSE 0 END);
UPDATE donation4isl d INNER JOIN ( SELECT SUM(Don_Ges) AS   Don_ges_DA, island_id AS d_island_id FROM donation2 d_tmp GROUP BY island_id) AS don INNER JOIN (SELECT COUNT(`id`) AS Sum_Anz_Cities_per_Av, island_id AS c2_island_id FROM city2 c GROUP BY island_id) AS aux_cit ON ( d.`island_id` = don.`d_island_id` AND d.`island_id` = aux_cit.`c2_island_id`) SET d.`Don_pro_City` = (CASE WHEN (don.`Don_ges_DA` > 0) THEN (don.`Don_ges_DA` / aux_cit.`Sum_Anz_Cities_per_Av`) ELSE 0 END);
UPDATE donation4isl d INNER JOIN ( SELECT SUM(DonH_Luxusminen_Ges) AS   DonH_Luxusminen_DA, island_id AS d_island_id FROM donation2 d_tmp GROUP BY island_id) AS don INNER JOIN (SELECT SUM((CASE WHEN tradegood_workers = 0 THEN 1 ELSE tradegood_workers END)) AS Sum_tradegood_workers, island_id AS c2_island_id FROM city2 c GROUP BY island_id) AS aux_cit ON ( d.`island_id` = don.`d_island_id` AND d.`island_id` = aux_cit.`c2_island_id`) SET d.`Don_pro_Tradegood_Worker` = (CASE WHEN (don.`DonH_Luxusminen_DA` > 0) THEN (don.`DonH_Luxusminen_DA` / aux_cit.`Sum_tradegood_workers`) ELSE 0 END);
UPDATE donation4isl d INNER JOIN ( SELECT SUM(Don_Saegewerk_Ges) AS   Don_Saegewerk_DA, island_id AS d_island_id FROM donation2 d_tmp GROUP BY island_id) AS don INNER JOIN (SELECT SUM((CASE WHEN resource_workers = 0 THEN 1 ELSE resource_workers END)) AS Sum_resource_workers, island_id AS c2_island_id FROM city2 c GROUP BY island_id) AS aux_cit ON ( d.`island_id` = don.`d_island_id` AND d.`island_id` = aux_cit.`c2_island_id`) SET d.`Don_pro_Resource_Worker` = (CASE WHEN (don.`Don_Saegewerk_DA` > 0) THEN (don.`Don_Saegewerk_DA` / aux_cit.`Sum_resource_workers`) ELSE 0 END);
UPDATE donation4isl d INNER JOIN ( SELECT SUM(Don_Wonder_Ges) AS   Don_Wonder_DA, island_id AS d_island_id FROM donation2 d_tmp GROUP BY island_id) AS don INNER JOIN (SELECT SUM((CASE WHEN priests = 0 THEN 1 ELSE priests END)) AS Sum_priests, c.island_id AS c2_island_id FROM city2 c INNER JOIN donation2 don2 ON c.island_id = don2.island_id AND c.owner_id = don2.avatar_id GROUP BY c.island_id) AS aux_cit ON ( d.`island_id` = don.`d_island_id` AND d.`island_id` = aux_cit.`c2_island_id`) SET d.`Don_pro_Priester` = (CASE WHEN (don.`Don_Wonder_DA` > 0) THEN (don.`Don_Wonder_DA` / aux_cit.`Sum_priests`) ELSE 0 END);
UPDATE donation4isl d INNER JOIN ( SELECT SUM(Don_Wonder_Anteil_Schwefel) AS   schwefel_don, island_id AS d_island_id FROM donation2 d_tmp GROUP BY island_id) AS don INNER JOIN (SELECT (`Schwefel_Ges_verb_lag_don`) AS Sum_schwefel_don, island_id AS d2_island_id FROM donation4i d2 GROUP BY island_id) AS aux_don ON ( d.`island_id` = don.`d_island_id` AND d.`island_id` = aux_don.`d2_island_id`) SET d.`Proz_Don_Anteil_Schwefel_von_Schwefel_Ges_verb_lag` = (CASE WHEN (don.`schwefel_don` > 0 AND  aux_don.`Sum_schwefel_don` > 0) THEN ((don.`schwefel_don` / aux_don.`Sum_schwefel_don`) * 100) ELSE 0 END);
