UPDATE donation4isl d INNER JOIN ( SELECT SUM(Don_Ges) AS   Avg_Don_Ges, island_id AS d_island_id FROM donation2 d_tmp INNER JOIN island ON d_tmp.island_id = island.id GROUP BY island_id) AS don INNER JOIN (SELECT (`Anz_Staedte_pro_Insel`) AS Sum_Anz_Staedte_pro_Insel, id AS i_id FROM island) AS aux_isl ON ( d.`island_id` = don.`d_island_id` AND d.`island_id` = aux_isl.`i_id`) SET d.`Avg_Don_Ges` = don.`Avg_Don_Ges` / aux_isl.`Sum_Anz_Staedte_pro_Insel`;
