UPDATE donation4isl d INNER JOIN ( SELECT AVG(Proz_Don_von_Res_Ges) AS   Proz_Don_von_Res_Ges, island_id AS d_island_id FROM donation2 GROUP BY island_id) AS don ON d.island_id = don.d_island_id SET d.`Avg_Proz_Don_von_Res_Ges` = don.`Proz_Don_von_Res_Ges`;
UPDATE donation4isl d INNER JOIN ( SELECT AVG(Proz_DonH_Lux_Ges) AS   Proz_Don_Lux_Ges, island_id AS d_island_id FROM donation2 GROUP BY island_id) AS don ON d.island_id = don.d_island_id SET d.`Avg_Proz_Don_Lux_Ges` = don.`Proz_Don_Lux_Ges`;

